# -*- coding: utf-8 -*-
"""Pure-diagnosis items for the Updated CMS derm masters.

Jaxon asked for about a quarter of each form to be pure diagnosis. The pool only
had 21 such questions, so each form was carrying 1-7 instead of 16. These are the
cleanest reference shape: a vignette, then five CONDITION NAMES and nothing else.
All the reasoning lives in the per-option explanations, which is why the options
here sit at reference length (median ~20 characters) with no descriptor attached.
"""
D2 = "2. General Dermatology I.pptx"
D3 = "3. Dermatology  II.pptx"
D4 = "4.  Cutaneous Bacterial Infections.pptx"
D6 = "6. Fungal and Viral Skin Infections - Jaquith.pptx"
D7 = "7. Benign Skin Lesions Prof Griffenkranz 8-25-2025-2.pptx"
D8 = "CMS I Dermatological Infestations - Shahsv.pptx"
D9 = "CMS I Pigmented Skin Lesions - Shahsv-2.pptx"
D10 = "Premalignant and Malignant Cutaneous Lesions - Jaquith.pptx"

IO = {
 D2: "c — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of dermatological conditions",
 D3: "a — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of dermatological conditions",
 D4: "a — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, referrals, patient education and prognosis of cutaneous bacterial infections",
 D6: "b — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of cutaneous viral and fungal infections",
 D7: "a — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis for benign skin lesions",
 D8: "a — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of dermatological infestations",
 D9: "a — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of pigmented skin lesions",
 D10: "1 — Compare and contrast the etiologies, epidemiology, risk factors, clinical manifestations, differential diagnosis, diagnostic testing, management, appropriate referrals, patient education, and prognosis of pre-malignant and malignant cutaneous lesions",
}

def Q(topic, deck, slide, stem, opts, c):
    return {"topic": topic, "io": IO[deck], "q": stem + " What is the most likely diagnosis?",
            "opts": opts, "c": c, "cite": f"{deck}, Slide {slide}"}

